import org.springframework.samples.petclinic.rest.validation.OwnerEmail;
import org.springframework.samples.petclinic.rest.validation.OwnerPostcode;
import org.springframework.samples.petclinic.rest.validation.OwnerRegistrationDate;
import org.springframework.samples.petclinic.rest.validation.OwnerTelephone;
import org.springframework.samples.petclinic.rest.validation.RequiredOwnerFields;
import org.springframework.samples.petclinic.service.ClinicService;
import org.springframework.samples.petclinic.util.AddressNormalizer;
import org.springframework.samples.petclinic.util.BusinessDays;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.CrossOrigin;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.util.UriComponentsBuilder;

import jakarta.transaction.Transactional;

/**
 * @author Vitaliy Fedoriv
 */

@RestController
@CrossOrigin(exposedHeaders = "errors, content-type")
@RequestMapping("/api")
public class OwnerRestControllerV1 implements OwnersApi {

    /** Maximum number of owners a single city may contain; creating another owner there is rejected. */
    static final int CITY_CAPACITY = 50;

    /** Maximum number of owners that may be created per (business-day adjusted) registration date; further creates are rejected. */
    static final int DAILY_OWNER_LIMIT = 100;

    /** Owners already created on the same registration date beyond which a new owner gets 'bulkSignupWarning'. */
    static final int BULK_SIGNUP_THRESHOLD = 80;

    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");

    private final ClinicService clinicService;

    private final OwnerMapper ownerMapper;

    private final PetMapper petMapper;

    private final VisitMapper visitMapper;

    public OwnerRestControllerV1(ClinicService clinicService,
                                 OwnerMapper ownerMapper,
                                 PetMapper petMapper,
                                 VisitMapper visitMapper) {
        this.clinicService = clinicService;
        this.ownerMapper = ownerMapper;
        this.petMapper = petMapper;
        this.visitMapper = visitMapper;
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
        Collection<Owner> owners;
        if (lastName != null) {
            owners = this.clinicService.findOwnerByLastName(lastName);
        } else {
            owners = this.clinicService.findAllOwners();
        }
        if (owners.isEmpty()) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Transactional
    @Override
    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
        List<String> missingFields = RequiredOwnerFields.missingFields(ownerFieldsDto);
        if (!missingFields.isEmpty()) {
            throw new MissingRequiredFieldsException(missingFields);
        }
        OwnerPostcode.validate(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
        OwnerEmail.validate(ownerFieldsDto.getEmail());
        OwnerRegistrationDate.validate(ownerFieldsDto.getRegistrationDate());
        HttpHeaders headers = new HttpHeaders();
        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
        owner.setTelephone(OwnerTelephone.normalize(ownerFieldsDto.getTelephone()));
        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
        applyAddress(owner, ownerFieldsDto);
        // The householdId is derived from (lastName, postcode) and is part of the identity key. An
        // existing household blocks the create unless the new owner declares it shares the household.
        owner.setHouseholdId(this.clinicService.householdIdOf(owner));
        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
        if (!declaredHouseholdMember && this.clinicService.householdExists(owner)) {
            throw new DuplicateHouseholdException(owner.getHouseholdId());
        }
        if (this.clinicService.ownerIdentityKeyExists(owner)) {
            throw new DuplicateIdentityException(owner.getIdentityKey());
        }
        if (this.clinicService.countOwnersInCity(ownerFieldsDto.getCity()) >= CITY_CAPACITY) {
            throw new CityCapacityExceededException(ownerFieldsDto.getCity(), CITY_CAPACITY);
        }
        LocalDate registrationDate = BusinessDays.rollForward(
            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
        long ownersCreatedToday = this.clinicService.countOwnersRegisteredOn(registrationDate);
        if (ownersCreatedToday >= DAILY_OWNER_LIMIT) {
            throw new DailyOwnerLimitExceededException(DAILY_OWNER_LIMIT);
        }
        owner.setRegistrationDate(registrationDate);
        owner.setBulkSignupWarning(ownersCreatedToday > BULK_SIGNUP_THRESHOLD);
        // A declared household member is not a suspected duplicate.
        owner.setPossibleDuplicateOf(declaredHouseholdMember ? null : this.clinicService.findPossibleDuplicateOf(owner));
        this.clinicService.saveOwner(owner);
        AUDIT.info("Owner created: id={}, customerCode={}, region={}, membershipNumber={}, checkDigit={}, "
                + "registrationDate={}, membershipPoints={}, membershipLevel={}",
            owner.getId(), owner.getCustomerCode(), ownerMapper.toLocality(owner),
            ownerMapper.toMembershipNumber(owner), ownerMapper.toCheckDigit(owner),
            owner.getRegistrationDate(), ownerMapper.toMembershipPoints(owner), ownerMapper.toMembershipLevel(owner));
        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
        headers.setLocation(UriComponentsBuilder.newInstance()
            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        String telephone = OwnerTelephone.normalize(ownerFieldsDto.getTelephone());
        OwnerPostcode.validate(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
        OwnerEmail.validate(ownerFieldsDto.getEmail());
        OwnerRegistrationDate.validate(ownerFieldsDto.getRegistrationDate());
        applyAddress(currentOwner, ownerFieldsDto);
        currentOwner.setCity(ownerFieldsDto.getCity());
        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
        currentOwner.setLastName(ownerFieldsDto.getLastName());
        currentOwner.setTelephone(telephone);
        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
        if (ownerFieldsDto.getRegistrationDate() != null) {
            currentOwner.setRegistrationDate(BusinessDays.rollForward(ownerFieldsDto.getRegistrationDate()));
        }
        if (ownerFieldsDto.getBirthDate() != null) {
            currentOwner.setBirthDate(ownerFieldsDto.getBirthDate());
        }
        currentOwner.setTitle(ownerFieldsDto.getTitle() == null ? null : ownerFieldsDto.getTitle().getValue());
        this.clinicService.saveOwner(currentOwner);
        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Transactional
    @Override
    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        this.clinicService.deleteOwner(owner);
        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        HttpHeaders headers = new HttpHeaders();
        Pet pet = petMapper.toPet(petFieldsDto);
        owner.setId(ownerId);
        pet.setOwner(owner);
        pet.getType().setName(null);
        this.clinicService.savePet(pet);
        PetDto petDto = petMapper.toPetDto(pet);
        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
            .buildAndExpand(pet.getId()).toUri());
        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner != null) {
            Pet currentPet = this.clinicService.findPetById(petId);
            if (currentPet != null) {
                currentPet.setBirthDate(petFieldsDto.getBirthDate());
                currentPet.setName(petFieldsDto.getName());
                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
                this.clinicService.savePet(currentPet);
                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
        HttpHeaders headers = new HttpHeaders();
        Visit visit = visitMapper.toVisit(visitFieldsDto);
        Pet pet = new Pet();
        pet.setId(petId);
        visit.setPet(pet);
        this.clinicService.saveVisit(visit);
        VisitDto visitDto = visitMapper.toVisitDto(visit);
        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
            .buildAndExpand(visit.getId()).toUri());
        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
    }


    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner != null) {
            Pet pet = owner.getPet(petId);
            if (pet != null) {
                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }

    /**
     * Stores the normalized structured address lines (absent when not supplied) and the composed
     * 'address': the structured lines when 'addressLine1' is present, otherwise the flat address.
     */
    private static void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
        owner.setAddressLine1(AddressNormalizer.normalizeOptional(ownerFieldsDto.getAddressLine1()));
        owner.setAddressLine2(owner.getAddressLine1() == null ? null
            : AddressNormalizer.normalizeOptional(ownerFieldsDto.getAddressLine2()));
        owner.setAddress(AddressNormalizer.compose(
            ownerFieldsDto.getAddressLine1(), ownerFieldsDto.getAddressLine2(), ownerFieldsDto.getAddress()));
    }

    private static String normalizeEmail(String email) {
        return email == null ? null : email.toLowerCase(Locale.ROOT);
    }
}
package org.springframework.samples.petclinic.rest.controller.v2;

import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageRequest;
import org.springframework.data.domain.Sort;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.api.OwnerV2Api;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
import org.springframework.samples.petclinic.service.ClinicService;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.CrossOrigin;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.bind.annotation.RequestMapping;

@RestController
@CrossOrigin(exposedHeaders = "errors, content-type")
@RequestMapping("/api")
public class OwnerRestControllerV2 implements OwnerV2Api {

    private final ClinicService clinicService;
    private final OwnerMapper ownerMapper;

    public OwnerRestControllerV2(ClinicService clinicService, OwnerMapper ownerMapper) {
        this.clinicService = clinicService;
        this.ownerMapper = ownerMapper;
    }

    @Override
    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    public ResponseEntity<OwnerPageDto> listOwnersPage(String lastName, Integer page, Integer size) {
        int pageNumber = page == null ? 0 : page;
        int pageSize = size == null ? 20 : size;
        Page<Owner> owners = this.clinicService.findOwners(
            lastName,
            PageRequest.of(pageNumber, pageSize, Sort.by("id")));
        return new ResponseEntity<>(ownerMapper.toOwnerPageDto(owners), HttpStatus.OK);
    }
}

content.content:
    Owner:
      title: Owner
      description: A pet owner.
      allOf:
        - $ref: '#/components/schemas/OwnerFields'
        - type: object
          properties:
            id:
              title: ID
              description: The ID of the pet owner.
              type: integer
              format: int32
              minimum: 0
              example: 1
              readOnly: true
            pets:
              title: Pets
              description: The pets owned by this individual including any booked vet visits.
              type: array
              items:
                $ref: '#/components/schemas/Pet'
              readOnly: true
            displayName:
              title: Display name
              description: The owner's name formatted as 'LastName, FirstName' from the stored names.
              type: string
              example: 'Franklin, George'
              readOnly: true
            initials:
              title: Initials
              description: The upper-cased first letters of the owner's first and last names, dot-separated with a trailing dot.
              type: string
              example: 'G.F.'
              readOnly: true
            customerCode:
              title: Customer code
              description: >-
                Assigned on create as '<REGION>-<HASH8>': the region whose postcode range contains
                the postcode (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099; when the postcode is absent
                or in no range, the region of the city as for 'locality', otherwise 'UNKNOWN'), a dash,
                and the first 8 upper-case hex characters of SHA-256 over the UTF-8 bytes of the
                normalized telephone followed by the last name.
              type: string
              example: 'NSW-3FA9C27B'
              readOnly: true
            checkDigit:
              title: Check digit
              description: >-
                The Luhn check digit (0-9) computed over the digits contained in 'customerCode',
                ignoring all non-digit characters. Absent when the owner has no customer code.
              type: integer
              format: int32
              minimum: 0
              maximum: 9
              example: 6
              readOnly: true
            householdId:
              title: Household ID
              description: >-
                Deterministic identifier shared by owners in the same household: the first 12
                lower-case hex characters of the SHA-256 of '<lastName>|<postcode>', with the last
                name trimmed, whitespace-collapsed and lower-cased. Owners with the same last name and
                postcode therefore always share it. Absent for owners without a postcode.
              type: string
              example: '3f2b8c1e7a4d'
              readOnly: true
            identityKey:
              title: Identity key
              description: >-
                Derived identity used for duplicate detection, formatted as
                '<telephone>|<email>|<householdId>' from the normalized telephone, the lower-cased
                email (empty when absent) and the household ID (empty when absent). Creating an owner
                whose whole identity key equals an existing owner's is rejected with 409 Conflict;
                owners differing in any part, e.g. household members with different telephones, are
                allowed.
              type: string
              example: '+61412345678|george.franklin@example.com|'
              readOnly: true
            namesakeCount:
              title: Namesake count
              description: >-
                Assigned on create: the number of owners that already existed before this owner was
                created with the same first name and last name, compared case-insensitively.
              type: integer
              format: int32
              minimum: 0
              example: 0
              readOnly: true
            membershipNumber:
              title: Membership number
              description: >-
                Formatted as '<customerCode>-M<YY>' where YY is the last two digits of the fiscal
                year (see 'fiscalYear') containing the registration date, e.g. 'NSW-3FA9C27B-M27'
                for a registration date of 2026-10-14. Absent when the owner has no customer code or
                registration date.
              type: string
package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
import org.springframework.samples.petclinic.rest.validation.OwnerPostcode;
import org.springframework.samples.petclinic.rest.validation.OwnerTelephone;
import org.springframework.samples.petclinic.util.FiscalYears;

import java.time.temporal.ChronoUnit;
import java.util.Collection;
import java.util.List;
import java.util.Map;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public interface OwnerMapper {

    Map<String, String> CITY_REGIONS = Map.of(
        "Sydney", "NSW",
        "Melbourne", "VIC",
        "Brisbane", "QLD");

    Map<String, String> REGION_TIMEZONES = Map.of(
        "NSW", "Australia/Sydney",
        "VIC", "Australia/Melbourne",
        "QLD", "Australia/Brisbane");

    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
    @Mapping(target = "initials", expression = "java(toInitials(owner))")
    @Mapping(target = "checkDigit", expression = "java(toCheckDigit(owner))")
    @Mapping(target = "membershipNumber", expression = "java(toMembershipNumber(owner))")
    @Mapping(target = "fiscalYear", expression = "java(toFiscalYear(owner))")
    @Mapping(target = "membershipPoints", expression = "java(toMembershipPoints(owner))")
    @Mapping(target = "membershipLevel", expression = "java(toMembershipLevel(owner))")
    @Mapping(target = "locality", expression = "java(toLocality(owner))")
    @Mapping(target = "contactPreference", expression = "java(toContactPreference(owner))")
    @Mapping(target = "bulkSignupWarning", expression = "java(Boolean.TRUE.equals(owner.getBulkSignupWarning()))")
    @Mapping(target = "possibleDuplicate", expression = "java(owner.getPossibleDuplicateOf() != null)")
    @Mapping(target = "ageBand", expression = "java(toAgeBand(owner))")
    @Mapping(target = "telephoneDisplay", expression = "java(toTelephoneDisplay(owner))")
    @Mapping(target = "timezone", expression = "java(toTimezone(owner))")
    @Mapping(target = "salutation", expression = "java(toSalutation(owner))")
    @Mapping(target = "sharesHousehold", ignore = true)
    OwnerDto toOwnerDto(Owner owner);

    /**
     * '&lt;title&gt; &lt;lastName&gt;', or just the last name when the owner has no title.
     */
    default String toSalutation(Owner owner) {
        return owner.getTitle() == null ? owner.getLastName() : owner.getTitle() + " " + owner.getLastName();
    }

    /**
     * The stored E.164 telephone formatted for humans, e.g. '+61 412 345 678'.
     */
    default String toTelephoneDisplay(Owner owner) {
        return OwnerTelephone.format(owner.getTelephone());
    }

    /**
     * The owner's age in completed years on the registration date: 'MINOR' under 18, 'ADULT' 18-64,
     * 'SENIOR' 65 or over. Absent when the owner has no birth date or registration date.
     */
    default String toAgeBand(Owner owner) {
        if (owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
            return null;
        }
        long age = ChronoUnit.YEARS.between(owner.getBirthDate(), owner.getRegistrationDate());
        if (age < 18) {
            return "MINOR";
        }
        return age < 65 ? "ADULT" : "SENIOR";
    }

    /**
     * The REGION part of the owner's customer code ('&lt;REGION&gt;-&lt;HASH8&gt;', optionally followed by a
     * '-&lt;n&gt;' de-duplication suffix); for owners without a
     * customer code, the region derived by {@link OwnerPostcode#regionOf(String, String)}.
     */
    default String toLocality(Owner owner) {
        String code = owner.getCustomerCode();
        int dash = code == null ? -1 : code.indexOf('-');
        if (dash > 0) {
            return code.substring(0, dash);
        }
        return OwnerPostcode.regionOf(owner.getPostcode(), owner.getCity());
    }

    /**
     * The IANA timezone of the owner's {@link #toLocality(Owner) locality} from {@link #REGION_TIMEZONES};
     * absent for any other locality.
     */
    default String toTimezone(Owner owner) {
        return REGION_TIMEZONES.get(toLocality(owner));
    }

    /**
     * 'EMAIL' when the owner has an email address, otherwise 'PHONE'.
     */
    default String toContactPreference(Owner owner) {
        return owner.getEmail() != null && !owner.getEmail().isBlank() ? "EMAIL" : "PHONE";
    }

    /** Membership points for an owner with an email address. */
    int EMAIL_MEMBERSHIP_POINTS = 2;

    /** Membership points for an owner without namesakes. */
    int NO_NAMESAKE_MEMBERSHIP_POINTS = 1;

    /** Membership points for a household of at least {@link #HOUSEHOLD_MEMBERSHIP_SIZE} members. */
    int HOUSEHOLD_MEMBERSHIP_POINTS = 2;

    /** The household size earning {@link #HOUSEHOLD_MEMBERSHIP_POINTS}. */
    int HOUSEHOLD_MEMBERSHIP_SIZE = 3;

    /** Membership points for a tenure of at least {@link #TENURE_MEMBERSHIP_FISCAL_YEARS} elapsed fiscal years. */
    int TENURE_MEMBERSHIP_POINTS = 3;

    /** {@link #TENURE_MEMBERSHIP_POINTS} requires a tenure of at least this many elapsed fiscal years. */
    int TENURE_MEMBERSHIP_FISCAL_YEARS = 1;

    /** The highest membership level. */
    int MAX_MEMBERSHIP_LEVEL = 4;

    /**
     * The membership points of a newly created owner. A new owner has zero tenure, so this never
     * includes {@link #TENURE_MEMBERSHIP_POINTS}.
     */
    default Integer toMembershipPoints(Owner owner) {
        return membershipPoints(owner, 0);
    }

    /**
     * The membership level of a newly created owner, derived from {@link #toMembershipPoints(Owner)}.
     */
    default Integer toMembershipLevel(Owner owner) {
        return membershipLevel(toMembershipPoints(owner));
    }

    /**
     * Starts at 0, adds {@link #EMAIL_MEMBERSHIP_POINTS} when an email is present,
     * {@link #NO_NAMESAKE_MEMBERSHIP_POINTS} when the owner has no namesakes,
     * {@link #HOUSEHOLD_MEMBERSHIP_POINTS} for a household of {@link #HOUSEHOLD_MEMBERSHIP_SIZE} or more
     * members and {@link #TENURE_MEMBERSHIP_POINTS} for a tenure of at least
     * {@link #TENURE_MEMBERSHIP_FISCAL_YEARS} elapsed fiscal years (see {@link FiscalYears#between}).
     */
    default int membershipPoints(Owner owner, long tenureFiscalYears) {
        int points = 0;
        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
            points += EMAIL_MEMBERSHIP_POINTS;
        }
        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
            points += NO_NAMESAKE_MEMBERSHIP_POINTS;
        }
        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= HOUSEHOLD_MEMBERSHIP_SIZE) {
            points += HOUSEHOLD_MEMBERSHIP_POINTS;
        }
        if (tenureFiscalYears >= TENURE_MEMBERSHIP_FISCAL_YEARS) {
            points += TENURE_MEMBERSHIP_POINTS;
        }
        return points;
    }

    /**
     * Maps membership points to a level: 1 for 0-1 points, 2 for 2-3, 3 for 4-5 and
     * {@link #MAX_MEMBERSHIP_LEVEL} for 6 or more.
     */
    default int membershipLevel(int points) {
        return Math.min(points / 2 + 1, MAX_MEMBERSHIP_LEVEL);
    }

    /**
     * 'FY&lt;YY&gt;' for the fiscal year (starting 1 July) containing the business-day adjusted
     * registration date; absent when the owner has no registration date.
     */
    default String toFiscalYear(Owner owner) {
        return FiscalYears.label(owner.getRegistrationDate());
    }

    /**
     * Builds the membership number '&lt;customerCode&gt;-M&lt;YY&gt;', where YY is the last two digits of
     * the fiscal year containing the registration date.
     */
    default String toMembershipNumber(Owner owner) {
        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
            return null;
        }
        return String.format("%s-M%02d", owner.getCustomerCode(),
            FiscalYears.twoDigit(owner.getRegistrationDate()));
    }

    /**
     * The Luhn check digit over the digits of the customer code, ignoring non-digit characters.
     */
    default Integer toCheckDigit(Owner owner) {
        String code = owner.getCustomerCode();
        if (code == null) {
            return null;
        }
        int sum = 0;
        boolean doubled = true;
        for (int i = code.length() - 1; i >= 0; i--) {
            char c = code.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int digit = c - '0';
            if (doubled) {
                digit *= 2;
                if (digit > 9) {
                    digit -= 9;
                }
            }
            sum += digit;
            doubled = !doubled;
        }
        return (10 - sum % 10) % 10;
    }

    default String toInitials(Owner owner) {
        return initial(owner.getFirstName()) + initial(owner.getLastName());
